/* From Uiverse.io by Bastiennnn  - Tags: animation, blue, card, code, hover effect, cool card, cardhover , card hover */
.__UIV_SCOPE__ .card {
  width: 300px;
  height: 400px;
  margin: 0 auto;
  background-color: #24233b;
  border-radius: 8px;
  z-index: 1;
  box-shadow: 0px 10px 10px rgb(73, 70, 92);
  transition: 0.5s;
}

.__UIV_SCOPE__ .card:hover {
  transform: translateY(-7px);
  box-shadow: 0px 10px 10px black;
}

.__UIV_SCOPE__ .top {
  display: flex;
  align-items: center;
  padding-left: 10px;
}

.__UIV_SCOPE__ .circle {
  padding: 0 4px;
}

.__UIV_SCOPE__ .circle2 {
  display: inline-block;
  align-items: center;
  width: 10px;
  height: 10px;
  padding: 1px;
  border-radius: 5px;
}

.__UIV_SCOPE__ .red {
  background-color: #ff605c;
}

.__UIV_SCOPE__ .yellow {
  background-color: #ffbd44;
}

.__UIV_SCOPE__ .green {
  background-color: #00ca4e;
}

.__UIV_SCOPE__ .header {
  margin: 5px;
  margin-top: 5px;
  border-radius: 5px;
}

.__UIV_SCOPE__ #title2 {
  color: white;
  padding-left: 50px;
  font-size: 15px;
}

.__UIV_SCOPE__ .code-container {
  text-align: center;
}
.__UIV_SCOPE__ #code {
  width: 270px;
  height: 350px;
  resize: none;
  background-color: rgb(73, 70, 92);
  border-radius: 5px;
  border: none;
  color: white;
  padding: 10px;
}
.__UIV_SCOPE__ #code:focus {
  outline: none !important;
}
